// Improved application with enhanced error handling and security best practices
// This version addresses common security vulnerabilities and improves robustness

const express = require('express');
const app = express();
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

// Security middleware
app.use(helmet()); // Set various HTTP headers for security
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(xss()); // Sanitize user input to prevent XSS
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});
app.use(limiter);

// Custom validation middleware
const validateQueryParams = (schema) => {
  return (req, res, next) => {
    // Simple validation - in production use Joi or express-validator
    for (const [key, value] of Object.entries(req.query)) {
      if (typeof value !== 'string' || value.length > 100) {
        return res.status(400).json({
          error: 'Invalid query parameter',
          message: `Parameter ${key} must be a string with max length 100`
        });
      }

      // Additional sanitization
      if (/[<>\"'%]/.test(value)) {
        return res.status(400).json({
          error: 'Invalid characters in query parameter',
          message: `Parameter ${key} contains invalid characters`
        });
      }
    }
    next();
  };
};

// Error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error('Error:', err);

  // Default error status
  const statusCode = res.statusCode !== 200 ? res.statusCode : 500;

  res.status(statusCode).json({
    error: true,
    message: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
};

// 404 handler
const notFoundHandler = (req, res) => {
  res.status(404).json({
    error: true,
    message: `Route ${req.originalUrl} not found`
  });
};

// Health check endpoint with validation
app.get('/health', validateQueryParams(), (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      service: 'user-service'
    });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with improved validation and error handling
app.get('/users', validateQueryParams({
  limit: { type: 'number', min: 1, max: 100 },
  offset: { type: 'number', min: 0 }
}), (req, res, next) => {
  try {
    // In a real application, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' }
    ];

    // Mock pagination based on query params
    const limit = parseInt(req.query.limit) || 10;
    const offset = parseInt(req.query.offset) || 0;

    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      success: true,
      count: paginatedUsers.length,
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: users.length
      }
    });
  } catch (error) {
    next(error);
  }
});

// Example POST endpoint with validation
app.post('/users', validateQueryParams(), (req, res, next) => {
  try {
    // Validate request body
    const { name, email } = req.body;

    if (!name || !email) {
      return res.status(400).json({
        error: true,
        message: 'Name and email are required fields'
      });
    }

    // Basic email validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return res.status(400).json({
        error: true,
        message: 'Invalid email format'
      });
    }

    // Name validation
    if (typeof name !== 'string' || name.length < 2 || name.length > 50) {
      return res.status(400).json({
        error: true,
        message: 'Name must be a string between 2 and 50 characters'
      });
    }

    // In a real app, you would save to database here
    const newUser = {
      id: Date.now(), // Mock ID generation
      name,
      email
    };

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: newUser
    });
  } catch (error) {
    next(error);
  }
});

// Apply error handling middleware last
app.use(notFoundHandler);
app.use(errorHandler);

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

