// Improved application with proper error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const { celebrate, Joi, errors } = require('celebrate');
const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(xss()); // Sanitize user input to prevent XSS
app.use(mongoSanitize()); // Prevent NoSQL injection

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// Health check endpoint with input validation
app.get('/health', 
  celebrate({
    query: Joi.object({
      // Optional query parameters with validation
      detailed: Joi.boolean().optional(),
    })
  }),
  (req, res) => {
    try {
      const response = {
        status: 'ok',
        timestamp: new Date().toISOString(),
        ...(req.query.detailed && { uptime: process.uptime() })
      };

      res.json(response);
    } catch (error) {
      res.status(500).json({ 
        error: 'Internal server error', 
        message: process.env.NODE_ENV === 'development' ? error.message : undefined 
      });
    }
  }
);

// Users endpoint with proper validation and error handling
app.get('/users', 
  celebrate({
    query: Joi.object({
      page: Joi.number().integer().min(1).default(1),
      limit: Joi.number().integer().min(1).max(100).default(10),
      sort: Joi.string().valid('name', 'email', 'id').optional(),
      search: Joi.string().max(50).optional().allow('')
    })
  }),
  (req, res) => {
    try {
      // Simulated database query with validated parameters
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply filtering based on validated search parameter
      let filteredUsers = users;
      if (req.query.search) {
        const searchTerm = req.query.search.toLowerCase();
        filteredUsers = users.filter(user => 
          user.name.toLowerCase().includes(searchTerm) || 
          user.email.toLowerCase().includes(searchTerm)
        );
      }

      // Apply sorting based on validated sort parameter
      if (req.query.sort) {
        filteredUsers.sort((a, b) => {
          if (a[req.query.sort] < b[req.query.sort]) return -1;
          if (a[req.query.sort] > b[req.query.sort]) return 1;
          return 0;
        });
      }

      // Apply pagination
      const page = parseInt(req.query.page);
      const limit = parseInt(req.query.limit);
      const startIndex = (page - 1) * limit;
      const endIndex = page * limit;
      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      res.json({
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: filteredUsers.length,
          totalPages: Math.ceil(filteredUsers.length / limit)
        }
      });
    } catch (error) {
      // Proper error handling with logging (in production, use a proper logger)
      console.error('Error in /users endpoint:', error);
      res.status(500).json({ 
        error: 'Internal server error', 
        message: process.env.NODE_ENV === 'development' ? error.message : undefined 
      });
    }
  }
);

// Example POST endpoint demonstrating input validation
app.post('/users', 
  celebrate({
    body: Joi.object({
      name: Joi.string().min(2).max(50).required(),
      email: Joi.string().email().required(),
      age: Joi.number().integer().min(0).max(150).optional()
    })
  }),
  (req, res) => {
    try {
      // In a real app, you would save to database here
      const newUser = {
        id: Date.now(), // Simple ID generation for demo
        ...req.body
      };

      res.status(201).json({ 
        message: 'User created successfully', 
        user: newUser 
      });
    } catch (error) {
      console.error('Error creating user:', error);
      res.status(500).json({ 
        error: 'Internal server error', 
        message: process.env.NODE_ENV === 'development' ? error.message : undefined 
      });
    }
  }
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Error handling middleware
app.use(errors()); // Celebrate error handler

// General error handling middleware
app.use((err, req, res, next) => {
  // Log error (in production, use proper logging service)
  console.error('Unhandled error:', err);

  // Set default status code if not set
  const statusCode = err.statusCode || 500;

  // Don't leak stack trace in production
  const response = {
    error: err.message || 'Internal server error'
  };

  if (process.env.NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

