// Improved application with enhanced error handling and security practices

const express = require('express');
const app = express();

// Middleware to parse JSON bodies
app.use(express.json());

// Security middleware - in a real app, you'd use helmet.js or similar
app.use((req, res, next) => {
  // Set security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Remove powered by header
  res.removeHeader('X-Powered-By');

  next();
});

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
  next();
});

// Health check endpoint with error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Users endpoint with input validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if any were expected
    // For example, if we supported filtering:
    // const { limit, offset } = req.query;
    // if (limit && isNaN(parseInt(limit))) {
    //   return res.status(400).json({ error: 'Limit must be a number' });
    // }

    // Simulate potential asynchronous operation that could fail
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // In a real app, this might come from a database
    res.json({
      success: true,
      data: users,
      count: users.length,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      success: false,
      message: 'Unable to retrieve users' 
    });
  }
});

// Example endpoint demonstrating input validation
app.get('/users/:id', (req, res) => {
  try {
    // Validate and sanitize input
    const userId = parseInt(req.params.id);

    if (isNaN(userId) || userId <= 0) {
      return res.status(400).json({ 
        success: false,
        message: 'Invalid user ID. Must be a positive integer.' 
      });
    }

    // Additional validation: check if ID is within reasonable bounds
    if (userId > 1000000) {
      return res.status(400).json({ 
        success: false,
        message: 'User ID is too large' 
      });
    }

    // Simulate fetching user (in real app, this would be a DB query)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ 
        success: false,
        message: 'User not found' 
      });
    }

    res.json({
      success: true,
      data: user
    });
  } catch (error) {
    console.error('Get user by ID error:', error);
    res.status(500).json({ 
      success: false,
      message: 'Internal server error' 
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({ 
    success: false,
    message: 'Route not found' 
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Global error handler:', error);

  // In production, don't leak error details
  const statusCode = error.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : error.message || 'Unknown error';

  res.status(statusCode).json({ 
    success: false,
    message: message,
    // Only include stack trace in development
    ...(process.env.NODE_ENV !== 'production' && { stack: error.stack })
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = { app, server };

