// Improved application with enhanced error handling and input validation
// Security best practices implemented

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(xss()); // Prevent XSS attacks
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests from this IP, please try again later.' }
});
app.use(limiter);

// Health check endpoint with input validation
app.get('/health', (req, res) => {
  // Validate query parameters if any
  const { detailed } = req.query;

  // Input validation
  if (detailed && detailed !== 'true' && detailed !== 'false') {
    return res.status(400).json({ 
      error: 'Invalid parameter', 
      message: 'The "detailed" parameter must be either "true" or "false"' 
    });
  }

  const response = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  };

  // Only include detailed info if requested and validated
  if (detailed === 'true') {
    response.memoryUsage = process.memoryUsage();
    response.nodeVersion = process.version;
  }

  res.json(response);
});

// Users endpoint with improved validation and error handling
app.get('/users', (req, res, next) => {
  try {
    // Validate and sanitize query parameters
    const { limit, offset, search } = req.query;

    // Parse and validate limit
    let parsedLimit = 10; // default
    if (limit !== undefined) {
      parsedLimit = parseInt(limit, 10);
      if (isNaN(parsedLimit) || parsedLimit <= 0 || parsedLimit > 100) {
        return res.status(400).json({ 
          error: 'Validation failed', 
          message: 'Limit must be a number between 1 and 100' 
        });
      }
    }

    // Parse and validate offset
    let parsedOffset = 0; // default
    if (offset !== undefined) {
      parsedOffset = parseInt(offset, 10);
      if (isNaN(parsedOffset) || parsedOffset < 0) {
        return res.status(400).json({ 
          error: 'Validation failed', 
          message: 'Offset must be a non-negative number' 
        });
      }
    }

    // Validate search parameter (if provided)
    if (search !== undefined) {
      if (typeof search !== 'string' || search.length > 50) {
        return res.status(400).json({ 
          error: 'Validation failed', 
          message: 'Search must be a string with maximum length of 50 characters' 
        });
      }
      // Additional sanitization for search (beyond xss-clean)
      const sanitizedSearch = search.replace(/[<>]/g, '');
    }

    // Mock user data (in real app, this would come from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply search filter if provided
    let filteredUsers = users;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchLower) || 
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(parsedOffset, parsedOffset + parsedLimit);

    res.json({
      count: filteredUsers.length,
      limit: parsedLimit,
      offset: parsedOffset,
      users: paginatedUsers
    });

  } catch (err) {
    // Pass errors to error handling middleware
    next(err);
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err); // Log error for debugging (in production, use proper logger)

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Prepare error response
  const errorResponse = {
    error: statusCode === 500 ? 'Internal Server Error' : 'Bad Request',
    message: process.env.NODE_ENV === 'production' 
      ? 'Something went wrong' 
      : err.message || 'An error occurred'
  };

  // Add validation errors if present
  if (err.validationErrors) {
    errorResponse.validationErrors = err.validationErrors;
  }

  res.status(statusCode).json(errorResponse);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = { app, server };

