app.use(xss()); // Sanitize against XSS
app.use(mongoSanitize()); // Sanitize against NoSQL injection
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Health check endpoint with input validation
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Users endpoint with proper error handling
app.get('/users', (req, res) => {
  try {
    // Even though no parameters are used, validate query parameters if any
    if (Object.keys(req.query).length > 0) {
      // Return 400 if unexpected query parameters are provided
      return res.status(400).json({ 
        error: 'Bad Request', 
        message: 'Unexpected query parameters' 
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  } catch (error) {
    // Log the error for debugging (in production, use proper logger)
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ 
      error: 'Internal Server Error', 
      message: 'Unable to retrieve users' 
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found', 
    message: `Route ${req.originalUrl} not found` 
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // Default to 500 if status code not set
  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    error: err.message || 'Internal Server Error',
    // Only include stack trace in development
