// Secure Express application with proper error handling and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { validate } = require('express-validation');
const Joi = require('joi');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const logger = require('./logger'); // Custom logger module

const app = express();

// Security Middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      fontSrc: ["'self'"],
      connectSrc: ["'self'"],
      frameSrc: ["'none'"],
      objectSrc: ["'none'"],
      upgradeInsecureRequests: []
    }
  },
  crossOriginEmbedderPolicy: false,
}));

// Prevent HTTP parameter pollution
app.use(hpp());

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// CORS configuration with specific origins
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : [],
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true
}));

// Request logging for security monitoring
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.get('User-Agent'),
    timestamp: new Date().toISOString()
  });
  next();
});

// Input validation schemas
const getUsersSchema = {
  query: Joi.object({
    limit: Joi.number().integer().min(1).max(100).default(10),
    offset: Joi.number().integer().min(0).default(0),
    search: Joi.string().max(50).allow('', null)
  })
};

const healthCheckSchema = {
  query: Joi.object({
    detailed: Joi.boolean().default(false)
  })
};

// Routes with proper error handling and validation

app.get('/health', validate(healthCheckSchema), (req, res) => {
  try {
    const response = {
      status: 'ok',
      timestamp: new Date().toISOString()
    };

    // Only include detailed info if requested and in appropriate environment
    if (req.query.detailed && process.env.NODE_ENV !== 'production') {
      response.uptime = process.uptime();
      response.memoryUsage = process.memoryUsage();
    }

    res.status(200).json(response);
  } catch (error) {
    logger.error('Health check failed:', { error: error.message });
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.get('/users', validate(getUsersSchema), (req, res) => {
  try {
    // Simulate database query with validated parameters
    const { limit, offset, search } = req.query;

    // In a real application, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' }
    ];

    // Apply search filter if provided
    let filteredUsers = users;
    if (search) {
      const searchTerm = search.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchTerm) || 
        user.email.toLowerCase().includes(searchTerm)
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.status(200).json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: filteredUsers.length,
        hasMore: offset + limit < filteredUsers.length
      }
    });
  } catch (error) {
    logger.error('Error fetching users:', { error: error.message, query: req.query });
    res.status(500).json({ error: 'Internal server error' });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  logger.warn(`Undefined route accessed: ${req.method} ${req.path}`, {
    ip: req.ip,
    userAgent: req.get('User-Agent')
  });
  res.status(404).json({ 
    error: 'Route not found',
    availableRoutes: ['GET /health', 'GET /users']
  });
});

// Centralized error handling middleware
app.use((error, req, res, next) => {
  // Log the error for debugging/security monitoring
  logger.error('Unhandled error:', {
    error: error.message,
    stack: process.env.NODE_ENV !== 'production' ? error.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Handle Joi validation errors
  if (error.isJoi) {
    return res.status(400).json({ 
      error: 'Validation failed', 
      details: error.details.map(detail => detail.message)
    });
  }

  // Handle express-validation errors
  if (error.status) {
    return res.status(error.status).json({ 
      error: error.message || 'Validation error' 
    });
  }

  // Handle specific known errors
  if (error.type === 'entity.too.large') {
    return res.status(413).json({ 
      error: 'Payload too large' 
    });
  }

  if (error.type === 'encoding.unsupported') {
    return res.status(415).json({ 
      error: 'Unsupported media type' 
    });
  }

  // Generic error response - don't leak internal details in production
  const statusCode = error.status || 500;
  const message = statusCode === 500 
    ? 'Internal server error' 
    : error.message || 'An error occurred';

  res.status(statusCode).json({ error: message });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Process terminated');
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  server.close(() => {
    logger.info('Process terminated');
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = app;

// Simple logger utility for security and application events
const winston = require('winston');
const { combine, timestamp, json, errors } = winston.format;

// Determine log level from environment
const logLevel = process.env.LOG_LEVEL || 'info';

// Create logger instance
const logger = winston.createLogger({
  level: logLevel,
  format: combine(
    errors({ stack: true }),
    timestamp(),
    json()
  ),
  transports: [
    // Console transport for development
    new winston.transports.Console({
      format: winston.format.combine(
        winston.format.colorize(),
        winston.format.simple()
      )
    })
  ]
});

// Add file transport in production
if (process.env.NODE_ENV === 'production') {
  logger.add(new winston.transports.File({ 
    filename: 'logs/error.log', 
    level: 'error' 
  }));
  logger.add(new winston.transports.File({ 
    filename: 'logs/combined.log' 
  }));
}

module.exports = logger;

