};

const handleValidationErrorDB = err => {
  const errors = Object.values(err.errors).map(el => el.message);
  const message = `Invalid input data. ${errors.join('. ')}`;
  return new AppError(message, 400);
};

// User routes with proper validation and error handling
const express = require('express');
const router = express.Router();
const { body, param, query, validationResult } = require('express-validator');

// Mock user data for demonstration
let users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' }
];

// Validation middleware
const validateUser = [
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters'),

  body('email')
    .trim()
    .notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Please provide a valid email')
    .normalizeEmail()
];

// GET all users with validation
router.get(
  '/',
  [
    query('limit')
      .optional()
      .isInt({ gt: 0, lte: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('sort')
      .optional()
      .isIn(['name', 'email', '-name', '-email'])
      .withMessage('Invalid sort parameter'),
    query('fields')
      .optional()
      .matches(/^[a-zA-Z, ]+$/)
      .withMessage('Fields can only contain letters, commas, and spaces')
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        status: 'fail',
        errors: errors.array()
      });
    }

    // Process valid query parameters
    let result = [...users];
    const { limit, sort, fields } = req.query;

    // Apply sorting
    if (sort) {
      const isDesc = sort.startsWith('-');
      const field = isDesc ? sort.substring(1) : sort;
      result.sort((a, b) => {
        if (a[field] < b[field]) return isDesc ? 1 : -1;
        if (a[field] > b[field]) return isDesc ? -1 : 1;
        return 0;
      });
    }

    // Apply field limiting
    if (fields) {
      const requestedFields = fields.split(',').map(field => field.trim());
      result = result.map(user => {
        const limitedUser = {};
        requestedFields.forEach(field => {
          if (user[field] !== undefined) {
            limitedUser[field] = user[field];
          }
        });
        return limitedUser;
      });
    }

    // Apply limit
    if (limit) {
      result = result.slice(0, parseInt(limit));
    }

    res.json({
      status: 'success',
      results: result.length,
      data: {
        users: result
      }
    });
  }
);

// GET specific user by ID
router.get(
  '/:id',
  [
    param('id')
      .isInt({ gt: 0 })
      .withMessage('User ID must be a positive integer')
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        status: 'fail',
        errors: errors.array()
      });
    }

    const id = parseInt(req.params.id);
    const user = users.find(u => u.id === id);

    if (!user) {
      return res.status(404).json({
        status: 'fail',
        message: 'No user found with that ID'
      });
    }

    res.json({
      status: 'success',
      data: {
        user
      }
    });
  }
);

// POST create new user
router.post(
  '/',
  validateUser,
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        status: 'fail',
        errors: errors.array()
      });
    }

    const newUser = {
      id: users.length > 0 ? Math.max(...users.map(u => u.id)) + 1 : 1,
      name: req.body.name.trim(),
      email: req.body.email.trim().toLowerCase()
    };

    users.push(newUser);

    res.status(201).json({
      status: 'success',
      data: {
        user: newUser
      }
    });
  }
);

// PATCH update user
router.patch(
  '/:id',
  [
    param('id')
      .isInt({ gt: 0 })
      .withMessage('User ID must be a positive integer'),
    body('name')
      .optional()
      .trim()
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2 and 50 characters'),
    body('email')
      .optional()
      .trim()
      .isEmail()
      .withMessage('Please provide a valid email')
      .normalizeEmail()
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        status: 'fail',
        errors: errors.array()
      });
    }

    const id = parseInt(req.params.id);
    const userIndex = users.findIndex(u => u.id === id);

    if (userIndex === -1) {
      return res.status(404).json({
        status: 'fail',
        message: 'No user found with that ID'
      });
    }

    // Update only provided fields
    if (req.body.name !== undefined) {
      users[userIndex].name = req.body.name.trim();
    }
    if (req.body.email !== undefined) {
      users[userIndex].email = req.body.email.trim().toLowerCase();
    }

    res.json({
      status: 'success',
      data: {
        user: users[userIndex]
      }
    });
  }
);

// DELETE user
router.delete(
  '/:id',
  [
    param('id')
      .isInt({ gt: 0 })
      .withMessage('User ID must be a positive integer')
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        status: 'fail',
        errors: errors.array()
      });
    }

    const id = parseInt(req.params.id);
    const userIndex = users.findIndex(u => u.id === id);

    if (userIndex === -1) {
      return res.status(404).json({
        status: 'fail',
        message: 'No user found with that ID'
      });
    }

    const deletedUser = users.splice(userIndex, 1)[0];

    res.status(204).json({
      status: 'success',
      data: null
    });
  }
);

module.exports = router;

